import pandas as pd

def clean(df):
    df = df.drop_duplicates().reset_index(drop=True)
    df['body_mass_g'] = df['body_mass_g'].astype(str).str.replace(',', '').astype(float)
    df['island'] = df['island'].str.strip().replace({'Torgerson': 'Torgersen', 'Bisco': 'Biscoe'})
    df['sex'] = df['sex'].str.strip().str.lower()
    return df

def answer(df):
    return df.groupby('species')['body_mass_g'].sum().to_dict()
